$lines = Get-Content REFACTOR-PLAN.md -Encoding UTF8
foreach ($n in 129,199,373,427,428,461,519,522,544,558,566,592,594,733,812,871) {
  Write-Output "----- L$n -----"
  Write-Output $lines[$n-1]
}

$t = [System.IO.File]::ReadAllText((Resolve-Path 'REFACTOR-PLAN.md'))
$map = @{}
foreach ($ch in $t.ToCharArray()) {
  $c = [int][char]$ch
  if ($c -gt 126) { if ($map.ContainsKey($c)) { $map[$c]++ } else { $map[$c] = 1 } }
}
$map.GetEnumerator() | Sort-Object Value -Descending | ForEach-Object {
  "U+{0:X4}  count={1}" -f $_.Key, $_.Value
}

Write-Output "=== L1: LoginPage creds ==="; (Get-Content src/components/LoginPage.tsx)[15..26] | ForEach-Object { $_.Trim() }
