$t=[System.IO.File]::ReadAllText((Resolve-Path 'REFACTOR-PLAN.md'))
$words=@('consequence','remotely',' but ',' the ',' and ',' with ',' from ','should be','can be','wajib ada','done','start','build','good','bad','value','source','target group','semua file','yang mana','apa yang','current','next step','same as','perLUAN','ngerti','jadi','kayak','banget')
$found=@{}
foreach($w in $words){
  $c=([regex]::Matches($t,[regex]::Escape($w))).Count
  if($c -gt 0){ $found[$w]=$c }
}
$found.GetEnumerator()|Sort-Object Value -Descending|ForEach-Object{ "{0,3}x  '{1}'" -f $_.Value,$_.Key }

$p='REFACTOR-PLAN.md'
$t=[System.IO.File]::ReadAllText((Resolve-Path $p))
$t=$t.Replace('## FASE 4 - Refactor Monolith (ZERO KEHILANGAN FUNGSI)',"## $([char]0x2705) FASE 4 - Refactor Monolith (ZERO KEHILANGAN FUNGSI)")
[System.IO.File]::WriteAllText((Resolve-Path $p),$t,(New-Object System.Text.UTF8Encoding $false))
$m=@{}
foreach($ch in [System.IO.File]::ReadAllText((Resolve-Path $p)).ToCharArray()){ $c=[int][char]$ch; if($c -gt 126){ if($m.ContainsKey($c)){$m[$c]++}else{$m[$c]=1} } }
Write-Output "=== final codepoint audit ==="
$m.GetEnumerator()|Sort-Object Value -Descending|ForEach-Object{ "U+{0:X4} x{1}" -f $_.Key,$_.Value }
Write-Output "`n=== phases ==="
(Select-String -Path $p -Pattern '^## .*FASE').Count
